rules.rule:
MASTER TEMPLATE. line5 is produced by CPython's urllib.parse.urlunsplit(scheme_or_empty, netloc, path, query, fragment) followed by two furl fix-ups. Pseudocode (validated on 6129 inputs, 0 mismatches):

USES_NETLOC = {ftp,file,git,git+ssh,gopher,http,https,imap,itms-services,mms,nfs,nntp,prospero,rsync,rtsp,rtsps,rtspu,sftp,shttp,snews,svn,svn+ssh,telnet,wais,ws,wss}
DEFAULT_PORTS = {acap:674,afp:548,dict:2628,dns:53,file:-1,ftp:21,git:9418,gopher:70,http:80,https:443,imap:143,ipp:631,ipps:631,irc:194,ircs:6697,ldap:389,ldaps:636,mms:1755,msrp:2855,mtqp:1038,nfs:111,nntp:119,nntps:563,pop:110,prospero:1525,redis:6379,rsync:873,rtsp:554,rtsps:322,rtspu:5005,sftp:22,smb:445,snmp:161,ssh:22,svn:3690,telnet:23,ventrilo:3784,vnc:5900,wais:210,ws:80,wss:443}

// inputs: scheme (null | "" | lowercased str), host (null | "" | str),
//         username/password (null | DECODED str), port (null | int),
//         path == line3 (already percent-encoded), query == line4 verbatim,
//         fragment == str(f.fragment)

// 1. netloc
userpass = pctQuote(username ?? "")            // safe="" : keep only A-Za-z0-9 _ . - ~
if (password !== null) userpass += ":" + pctQuote(password)
if (userpass !== "" || username !== null) userpass += "@"
netloc = (host === null) ? null : idnaEncode(host)   // idna only when host has a codepoint >127
if (port !== null && port !== DEFAULT_PORTS[scheme]) netloc = (netloc ?? "") + ":" + decimal(port)
if (userpass !== "") netloc = userpass + (netloc ?? "")

// 2. CPython urlunsplit
s = scheme ?? ""; u = path
if (netloc /*non-null AND non-empty*/ || (s !== "" && USES_NETLOC.has(s) && u.slice(0,2) !== "//")) {
    if (u !== "" && u[0] !== "/") u = "/" + u
    u = "//" + (netloc ?? "") + u
}
if (s !== "") u = s + ":" + u
if (query !== "") u = u + "?" + query
if (fragment !== "") u = u + "#" + fragment

// 3. furl fix-ups that restore the ''-vs-None distinction
if (scheme === "")                    u = ":" + u
if (netloc === "" && scheme === null) u = "//" + u
return u
